-export const DEFAULT_PAGE_SIZE = 10;
+export const DEFAULT_PAGE_SIZE = 25;

-export function slicePage<T>(items: T[], page: number, size = DEFAULT_PAGE_SIZE): T[] {
+export function pageCount(total: number, size = DEFAULT_PAGE_SIZE): number {
+  return Math.ceil(total / size);
+}
+
+export function getPage<T>(items: T[], page: number, size = DEFAULT_PAGE_SIZE): T[] {
   const start = (page - 1) * size;
   return items.slice(start, start + size);
 }
